    <script>
        class ImagePreloader {
            constructor() {
                this.loadedImages = new Set();
                this.currentlyLoading = new Map();
            }
            async preload(url) {
                if (this.loadedImages.has(url)) return true;
                if (this.currentlyLoading.has(url)) return this.currentlyLoading.get(url);

                const loadPromise = new Promise((resolve, reject) => {
                    const img = new Image();
                    img.onload = () => {
                        this.loadedImages.add(url);
                        this.currentlyLoading.delete(url);
                        resolve(true);
                    };
                    img.onerror = () => {
                        this.currentlyLoading.delete(url);
                        reject(new Error(`Failed to load image: ${url}`));
                    };
                    img.src = url;
                });

                this.currentlyLoading.set(url, loadPromise);
                return loadPromise;
            }

            async preloadMany(urls, progressCallback) {
                const total = urls.length;
                let loaded = 0;

                const promises = urls.map(async url => {
                    try {
                        await this.preload(url);
                        loaded++;
                        if (progressCallback) {
                            progressCallback(loaded / total * 100);
                        }
                    } catch (error) {
                        console.error(error);
                    }
                });

                await Promise.all(promises);
            }
        }

        const gameState = {
            imagePreloader: new ImagePreloader(),
            currentAnimation: null,
            isUIHidden: false,
        };

        function fadeInCharacter(characterElement) {
            characterElement.style.opacity = '0';
            characterElement.style.transition = 'opacity 0.3s ease';
            requestAnimationFrame(() => {
                characterElement.style.opacity = '1';
            });
        }

        function fadeOutCharacter(characterElement) {
            characterElement.style.transition = 'opacity 0.3s ease';
            characterElement.style.opacity = '0';
        }

        async function updateCharacters(scene, previousScene) {
            const currentSpeaker = scene.name;
            const char1 = document.getElementById('char1');

            if (currentSpeaker === "旁白") {
                fadeOutCharacter(char1);
                return;
            }

            if (previousScene && previousScene.name === currentSpeaker) {
                char1.src = scene.charimg;
                char1.style.opacity = '1';
                char1.style.transition = 'none';
            } else {
                fadeOutCharacter(char1);
                setTimeout(() => {
                    char1.src = scene.charimg;
                    fadeInCharacter(char1);
                }, 300);
            }
        }

        async function loadScene(index = gameData.currentScene, previousScene = null) {
            try {
                if (!gameData.scenes || !Array.isArray(gameData.scenes)) {
                    throw new Error('场景数据无效或不存在');
                }

                if (index < 0 || index >= gameData.scenes.length) {
                    throw new Error('场景索引超出范围');
                }

                const scene = gameData.scenes[index];

                if (!scene || typeof scene !== 'object') {
                    throw new Error('当前场景数据无效');
                }

                await updateBackground(scene, previousScene);
                await updateCharacters(scene, previousScene);

                const nameText = document.getElementById('character-name');
                nameText.textContent = scene.name;

                const dialogBox = document.getElementById('dialog-box');
                dialogBox.querySelector('.dialog-text').textContent = scene.text;
                dialogBox.style.opacity = "1";

                if (index > 0) {
                    await typeWriter(dialogBox.querySelector('.dialog-text'), scene.text);
                } else {
                    dialogBox.querySelector('.dialog-text').textContent = scene.text;
                }

                gameData.currentScene = index;


            } catch (error) {
                showToast(error.message);
                console.error('加载场景失败:', error);

                try {
                    clearCharacters(document.getElementById('char1'));
                    document.getElementById('dialog-box').querySelector('.dialog-text').textContent = '加载场景时发生错误...';
                    document.getElementById('character-name').textContent = '错误';
                } catch (recoveryError) {
                    console.error('恢复到安全状态失败:', recoveryError);
                }
            }
        }

        async function updateBackground(scene, previousScene) {
            document.getElementById('bg-layer').style.backgroundImage = `url(${scene.background})`;
        }

        function clearCharacters(char1) {
            char1.style.opacity = '0';
            char1.src = "";
        }

        async function initGame() {
            showLoading();
            try {
                const imageUrls = collectImageUrls();
                await gameState.imagePreloader.preloadMany(imageUrls, updateLoadingProgress);
                hideLoading();
                loadScene(0);
            } catch (error) {
                showToast('初始化失败: ' + error.message);
                console.error('初始化失败:', error);
                hideLoading();
            }
        }

        function collectImageUrls() {
            const urls = new Set();
            gameData.scenes.forEach(scene => {
                if (scene.background) urls.add(scene.background);
                if (scene.charimg) urls.add(scene.charimg);
            });
            urls.add(document.getElementById('noshiro-avatar').src);
            urls.add(document.getElementById('jiuyun-avatar').src);
            return Array.from(urls);
        }

        function updateLoadingProgress(progress) {
            const progressElement = document.querySelector('.loading-progress');
            if (progressElement) {
                progressElement.textContent = `${Math.round(progress)}%`;
            }
        }

        function showLoading() {
            document.getElementById('loading-screen').style.display = 'flex';
        }

        function hideLoading() {
            document.getElementById('loading-screen').style.display = 'none';
        }

        function showToast(message) {
            alert(message);
        }

        const gameData = {
            scenes: [

  ],
            options: ["$1", "$2", "$3"],
            currentScene: 0
        };

        let isTyping = false;
        let currentText = '';
        let currentTimeout = null;
        let isAutoPlay = false;
        let isFastForward = false;
        let history = [];
        let isStatusBarFlipped = false;
        let historyRecordedForCurrentScene = false;

        function showChoices() {
            const choicesContainer = document.getElementById('choices-container');
            choicesContainer.innerHTML = '';
            gameData.options.forEach(option => {
                const button = document.createElement('button');
                button.textContent = option;
                button.classList.add('option');
                button.addEventListener('click', () => {
                    console.log('选项被点击:', option);
                    sendMessage(option);
                    hideChoices();
                });
                choicesContainer.appendChild(button);
            });
            choicesContainer.style.display = 'flex';
        }

        function hideChoices() {
            const choicesContainer = document.getElementById('choices-container');
            choicesContainer.style.display = 'none';
        }

        function sendMessage(message) {
            triggerSlash('/send ' + message);
        }

        function typeWriter(element, text, speed = 50) {
            return new Promise(resolve => {
                let index = 0;
                currentText = text;
                element.textContent = '';
                isTyping = true;
                const addChar = () => {
                    if (index < text.length) {
                        currentTimeout = setTimeout(() => {
                            element.textContent += text[index++];
                            addChar();
                        }, isFastForward ? speed / 10 : speed);
                    } else {
                        isTyping = false;
                        if (isAutoPlay || isFastForward) {
                            setTimeout(() => {
                                changeScene(1);
                            }, 100);
                        }
                        resolve();
                    }
                };
                addChar();
            });
        }

        async function changeScene(delta) {
            const nextSceneIndex = gameData.currentScene + delta;
            const choicesContainer = document.getElementById('choices-container');

            if (nextSceneIndex >= 0 && nextSceneIndex < gameData.scenes.length) {
                const previousScene = gameData.scenes[gameData.currentScene];

                hideChoices();

                gameData.currentScene = nextSceneIndex;
                historyRecordedForCurrentScene = false;
                await loadScene(gameData.currentScene, previousScene);
            } else {
                if (nextSceneIndex === gameData.scenes.length) {
                    showChoices();
                }
                if (nextSceneIndex < 0) {
                    hideChoices();
                }

                if (isFastForward) {
                    isFastForward = false;
                    document.getElementById('skip-button').innerHTML = '跳过 <i class="fas fa-forward"></i>';
                }
            }
        }

        document.getElementById('history-button').addEventListener('click', () => {
            if (gameState.isUIHidden) return;
            const historyModal = document.getElementById('history-modal');
            const historyList = document.getElementById('history-list');
            historyList.innerHTML = '';

            const historyCopy = [...history];
            historyCopy.forEach((item, index) => {
                const historyItem = document.createElement('div');
                historyItem.className = 'history-item';
                historyItem.innerHTML = `
                    <div class="character-name">${item.name}</div>
                    <div class="dialog-text">${item.text}</div>
                `;
                historyList.appendChild(historyItem);
            });
            historyModal.style.display = 'block';
        });

        document.getElementById('close-history-modal').addEventListener('click', () => {
            document.getElementById('history-modal').style.display = 'none';
        });

        document.getElementById('auto-button').addEventListener('click', () => {
            if (gameState.isUIHidden) return;
            isAutoPlay = !isAutoPlay;
            const autoButton = document.getElementById('auto-button');
            autoButton.innerHTML = isAutoPlay ? '停止 <i class="fas fa-sync-alt"></i>' : '自动 <i class="fas fa-sync-alt"></i>';

            if (isAutoPlay && !isTyping) {
                changeScene(1);
            }
        });

        document.getElementById('skip-button').addEventListener('click', () => {
            if (gameState.isUIHidden) return;
            isFastForward = !isFastForward;
            const skipButton = document.getElementById('skip-button');
            skipButton.innerHTML = isFastForward ? '停止 <i class="fas fa-forward"></i>' : '跳过 <i class="fas fa-forward"></i>';

            if (isFastForward && !isTyping) {
                changeScene(1);
            }
        });

        const responsiveContainer = document.getElementById('responsive-container');

        document.getElementById('dialog-box').addEventListener('click', async (event) => {
            if (gameState.isUIHidden) return;
            const dialogBox = document.getElementById('dialog-box');
            const rect = dialogBox.getBoundingClientRect();
            const clickX = event.clientX;

            let delta = 0;
            let isBackwardNavigation = false;

            if (clickX < rect.left + rect.width / 2) {
                delta = -1;
                isBackwardNavigation = true;
            } else {
                delta = 1;
            }

            if (delta > 0 && !historyRecordedForCurrentScene) {
                const currentSceneData = gameData.scenes[gameData.currentScene];
                history.push({
                    name: currentSceneData.name,
                    text: currentSceneData.text
                });
                historyRecordedForCurrentScene = true;
            }


            if (isTyping) {
                clearTimeout(currentTimeout);
                dialogBox.querySelector('.dialog-text').textContent = currentText;
                isTyping = false;
            } else {
                await changeScene(delta);
            }

            if (isAutoPlay || isFastForward) {
                isAutoPlay = false;
                isFastForward = false;
                document.getElementById('auto-button').innerHTML = '自动 <i class="fas fa-sync-alt"></i>';
                document.getElementById('skip-button').innerHTML = '跳过 <i class="fas fa-forward"></i>';
            }
        });

        document.addEventListener('keydown', async (e) => {
            if (gameState.isUIHidden) return;
            let isBackwardNavigation = false;
            let delta = 0;

            if (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ') {
                delta = 1;
            }
            if (e.key === 'ArrowLeft') {
                delta = -1;
                isBackwardNavigation = true;
            }

            if (delta > 0 && !historyRecordedForCurrentScene && (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ')) {
                const currentSceneData = gameData.scenes[gameData.currentScene];
                history.push({
                    name: currentSceneData.name,
                    text: currentSceneData.text
                });
                historyRecordedForCurrentScene = true;
            }


            if (e.key === 'ArrowRight' || e.key === 'ArrowLeft' || e.key === 'Enter' || e.key === ' ') {
                await changeScene(delta);
            }


            if (isAutoPlay || isFastForward) {
                isAutoPlay = false;
                isFastForward = false;
                document.getElementById('auto-button').innerHTML = '自动 <i class="fas fa-sync-alt"></i>';
                document.getElementById('skip-button').innerHTML = '跳过 <i class="fas fa-forward"></i>';
            }
        });

        const statusBarFlipContainer = document.getElementById('status-bar-flip-container');
        const statusBar = document.getElementById('status-bar');
        const noshiroAvatar = document.getElementById('noshiro-avatar');
        const jiuyunAvatar = document.getElementById('jiuyun-avatar');

        document.getElementById('character-name').addEventListener('click', (event) => {
            if (gameState.isUIHidden) return;
            event.stopPropagation();
            statusBarFlipContainer.classList.toggle('show');
        });

        noshiroAvatar.addEventListener('click', (event) => {
            if (gameState.isUIHidden) return;
            event.stopPropagation();
            statusBar.classList.add('flipped');
            isStatusBarFlipped = true;
        });

        jiuyunAvatar.addEventListener('click', (event) => {
            if (gameState.isUIHidden) return;
            event.stopPropagation();
            statusBar.classList.remove('flipped');
            isStatusBarFlipped = false;
        });

        document.addEventListener('click', (event) => {
            const isClickInsideStatusBar = statusBarFlipContainer.contains(event.target);
            const isClickOnCharacterName = event.target.closest('.character-name-container');
            const isClickOnCenterArea = document.getElementById('center-click-area').contains(event.target);

            if (!isClickInsideStatusBar && !isClickOnCharacterName && !isClickOnCenterArea) {
                statusBarFlipContainer.classList.remove('show');
                statusBar.classList.remove('flipped');
                isStatusBarFlipped = false;
            }
        });

        const centerClickArea = document.getElementById('center-click-area');
        const dialogBoxElement = document.getElementById('dialog-box');
        const historyButtonElement = document.getElementById('history-button');
        const autoButtonElement = document.getElementById('auto-button');
        const skipButtonElement = document.getElementById('skip-button');
        const choicesContainerElement = document.getElementById('choices-container');

        function toggleUIHidden() {
            gameState.isUIHidden = !gameState.isUIHidden;

            dialogBoxElement.classList.toggle('ui-hidden', gameState.isUIHidden);
            historyButtonElement.classList.toggle('ui-hidden', gameState.isUIHidden);
            autoButtonElement.classList.toggle('ui-hidden', gameState.isUIHidden);
            skipButtonElement.classList.toggle('ui-hidden', gameState.isUIHidden);
            choicesContainerElement.classList.toggle('ui-hidden', gameState.isUIHidden);

            autoButtonElement.disabled = gameState.isUIHidden;
            skipButtonElement.disabled = gameState.isUIHidden;
            historyButtonElement.disabled = gameState.isUIHidden;

            if (gameState.isUIHidden) {
                isAutoPlay = false;
                isFastForward = false;
                autoButtonElement.innerHTML = '自动 <i class="fas fa-sync-alt"></i>';
                skipButtonElement.innerHTML = '跳过 <i class="fas fa-forward"></i>';
            }
        }

        centerClickArea.addEventListener('click', (event) => {
            if (document.getElementById('history-modal').style.display === 'block' || statusBarFlipContainer.classList.contains('show')) {
                return;
            }
            event.stopPropagation();
            toggleUIHidden();
        });


        const songFile = "$4";

        if (songFile) {
            const audioUrl = `https://files.catbox.moe/${songFile}`;
            triggerSlash(`/audioselect type=bgm ${audioUrl}|/audiomode type=bgm mode=single|/audioplay type=bgm`);
        } else {
            triggerSlash(`/echo "BGM '$4' not found or invalid"`);
        }

        initGame();
    </script>
<!-- disable-default-loading -->
</body>
</html>
