    </style>
</head>

<body>
    <div id="loading-screen"
        style="display: flex; justify-content: center; align-items: center; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.9); z-index: 1001; color: white; font-size: 20px; font-family: sans-serif;">
