    <div class="status-bar-flip-container" id="status-bar-flip-container">
        <div class="status-bar" id="status-bar">
            <div class="status-bar-front" id="noshiro-status-bar-container">
                <img class="avatar" src="https://files.catbox.moe/skds1s.png" alt="能代 Avatar" id="noshiro-avatar" />
                <div class="status-item">
