                <div class="status-item">
                    <span class="status-label">
                        <i class="fas fa-tshirt"></i>衣着:
                    </span>
                    <span class="status-value" id="jiuyun-cloth-status">$3</span>
                </div>
                <div class="status-item">
                    <span class="status-label">
                        <i class="fas fa-heart" style="color: red;"></i>好感度:
                    </span>
                    <div class="heart-progress">
                        <i class="fas fa-heart heart-background"></i>
                        <i class="fas fa-heart heart-fill" id="jiuyun-affection-heart"
                            style="background-image: linear-gradient(to top, #ff6b6b 78%, transparent 78%);"></i>
