<body>
    <div id="responsive-container">
        <div id="bg-layer"></div>
        <div id="character-layer">
            <img class="character" id="char1" src="" alt="">
        </div>

        <!-- 角色名显示 -->
        <div id="name-container">
            <span id="character-name">角色名</span>
        </div>

        <!-- 对话框 -->
        <div id="dialog-box">对话内容</div>
    </div>

<script>
        const gameData = {
            scenes: [$1],
        currentScene: 0,
    };

    let isTyping = false;  // 标记是否正在逐字输出
    let currentText = '';  // 当前显示的文本内容
    let currentTimeout = null; // 当前正在执行的timeout，方便清理

    // 逐字输出函数
    function typeWriter(element, text, speed = 50) {
        let index = 0;
        currentText = text;
        element.textContent = '';
        const addChar = () => {
            if (index < text.length) {
                currentTimeout = setTimeout(() => {
                    element.textContent += text[index++];
                    addChar();
                }, speed);
            }
        };
        addChar();
    }

    // 加载场景内容
    function loadScene() {
        const scene = gameData.scenes[gameData.currentScene];

        // 设置背景
        document.getElementById('bg-layer').style.backgroundImage = `url(${scene.background})`;

        // 设置角色图像
        const charImg = document.getElementById('char1');
        charImg.src = scene.charimg;
        charImg.style.opacity = '1';

        // 设置角色名
        document.getElementById('character-name').textContent = scene.name;

        // 逐字输出对话框文本
        const dialogBox = document.getElementById('dialog-box');
        if (!isTyping) {
            typeWriter(dialogBox, scene.text);
            isTyping = true;
        } else {
            dialogBox.textContent = scene.text;
            isTyping = false;
        }
    }

    // 切换场景
    function changeScene(delta) {
        if (gameData.currentScene + delta >= 0 && gameData.currentScene + delta < gameData.scenes.length) {
            gameData.currentScene += delta;
            loadScene();
        }
    }

    // 点击对话框，根据点击位置切换场景
    document.getElementById('dialog-box').addEventListener('click', (event) => {
        const dialogBox = document.getElementById('dialog-box');
        const rect = dialogBox.getBoundingClientRect();
        const clickX = event.clientX;

        if (isTyping) {
            clearTimeout(currentTimeout);  // 停止逐字输出
            dialogBox.textContent = currentText;
            isTyping = false;
        } else {
            if (clickX < rect.left + rect.width / 2) {
                // 点击左侧，切换到上一个场景
                changeScene(-1);
            } else {
                // 点击右侧，切换到下一个场景
                changeScene(1);
            }
        }
    });

    // 键盘事件：右箭头或回车键切换到下一个场景，左箭头键切换到上一个场景
    document.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowRight' || e.key === 'Enter') changeScene(1);
        if (e.key === 'ArrowLeft') changeScene(-1);
    });

    // 初始化加载场景
    loadScene();
</script>
</body>
</html>
